"""日次から月末の系列を作る（adjclose と close＋分配の2通り）＋壊れの検査"""
import os, sys, json, math, datetime
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import fetch as FE
h = FE.h
LAST = 202608              # 2026-09 は途中の月

def daily(sym):
    r = FE.get(sym, '1d')['chart']['result'][0]
    q = r['indicators']['quote'][0]
    adj = r['indicators']['adjclose'][0]['adjclose']
    ev = r.get('events') or {}
    divs = {}
    for kind in ('dividends', 'capitalGains'):
        for k, v in (ev.get(kind) or {}).items():
            d = datetime.datetime.utcfromtimestamp(int(v['date'])).date()
            divs[d] = divs.get(d, 0.0) + float(v['amount'])
    splits = ev.get('splits') or {}
    rows = []
    for t, c, a in zip(r['timestamp'], q['close'], adj):
        if c is None or a is None:
            continue
        rows.append((datetime.datetime.utcfromtimestamp(t).date(), float(c), float(a)))
    return rows, divs, splits

def monthly(sym):
    rows, divs, splits = daily(sym)
    # adjclose の月末
    me_adj, me_cls = {}, {}
    for d, c, a in rows:
        m = d.year * 100 + d.month
        me_adj[m] = a; me_cls[m] = c
    ks = sorted(me_adj)
    ret_adj = {b: me_adj[b] / me_adj[a] - 1 for a, b in zip(ks, ks[1:]) if h.add_months(a, 1) == b}
    # close＋分配（権利落ち日に再投資）
    idx = 1.0; me_tr = {}
    prev = None
    used = set()
    for d, c, a in rows:
        if prev is not None:
            dv = divs.get(d, 0.0)
            if dv:
                used.add(d)
            idx *= (c + dv) / prev
        prev = c
        me_tr[d.year * 100 + d.month] = idx
    ret_tr = {b: me_tr[b] / me_tr[a] - 1 for a, b in zip(ks, ks[1:]) if h.add_months(a, 1) == b}
    lost = sorted(str(d) for d in divs if d not in used and d >= rows[0][0])
    # 最初の月（途中から始まる月）は落とす: 最初の月末から数える＝ret は2か月目から（上の作り方で自然にそうなる）
    ret_adj = {m: v for m, v in ret_adj.items() if m <= LAST}
    ret_tr = {m: v for m, v in ret_tr.items() if m <= LAST}
    return ret_adj, ret_tr, {'first_day': str(rows[0][0]), 'last_day': str(rows[-1][0]), 'n_div': len(divs), 'splits': len(splits), 'lost_div': lost}

def check(sym):
    ra, rt, info = monthly(sym)
    ms = sorted(set(ra) & set(rt))
    diffs = [(m, (ra[m] - rt[m]) * 100) for m in ms]
    ca = h.cagr(ra, ms[0], ms[-1]); ct = h.cagr(rt, ms[0], ms[-1])
    worst = sorted(diffs, key=lambda x: -abs(x[1]))[:3]
    broken = any(abs(x[1]) > 0.5 for x in diffs) or abs(ca - ct) * 100 > 0.10
    # 月足（interval=1mo）の adjclose とも照らす
    j = FE.get(sym, '1mo')['chart']['result'][0]
    mo = {}
    for t, a in zip(j['timestamp'], j['indicators']['adjclose'][0]['adjclose']):
        if a is None: continue
        d = datetime.datetime.utcfromtimestamp(t + (j['meta'].get('gmtoffset') or 0))
        mo[d.year * 100 + d.month] = a
    rmo = {m: v for m, v in h.px_to_ret(mo).items() if m <= LAST}
    ms2 = sorted(set(rmo) & set(ra))
    d2 = max((abs(rmo[m] - ra[m]) * 100 for m in ms2), default=None)
    return dict(info, months=len(ms), first_month=ms[0], cagr_adjclose=round(ca * 100, 3), cagr_close_plus_div=round(ct * 100, 3),
                diff_pct_yr=round((ca - ct) * 100, 3), max_abs_month_diff_pct=round(max(abs(x[1]) for x in diffs), 3),
                worst=[[m, round(v, 3)] for m, v in worst], broken=broken,
                max_abs_diff_vs_1mo_bars_pct=round(d2, 3) if d2 is not None else None)

def series(sym):
    """主の系列: 壊れていなければ adjclose、壊れていれば close＋分配"""
    ra, rt, info = monthly(sym)
    c = check(sym)
    return (rt if c['broken'] else ra), c

if __name__ == '__main__':
    for s in FE.SYMS:
        print(s, json.dumps(check(s), ensure_ascii=False))

