"""凍結した indmom を世界の業種ETF 10本へ写す（検証・壊しに行く側）。読むだけ。書くのは scratchpad と out/edge/verify_indmom_global.json だけ"""
import os, sys, json, math, statistics as S, datetime, copy
SP = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, SP)
import fetch as FE                      # EDGE_PHASE=holdout を立て、harness.CACHE を scratchpad へ差し替える
import data as D
h = FE.h
assert h.PHASE == 'holdout'
sys.path.insert(0, '/home/user/ccf-gate/night/edge')
import fam_indmom as F                  # 凍結した規則の関数をそのまま呼ぶ

SPEC_DOC = json.load(open('/home/user/ccf-gate/out/edge/spec_indmom.json', encoding='utf-8'))
FROZEN = SPEC_DOC['spec']
FRAC = FROZEN['k'] / FROZEN['n']
COST = 0.001
MAIN = 'IXN IXJ IXG IXC IXP EXI KXI RXI MXI JXI'.split()
VANG = 'VGT VHT VFH VDE VIS VDC VPU VAW VCR VOX'.split()
LAST = D.LAST


def k_of(N):
    return max(1, int(math.floor(N * FRAC + 0.5)))


def decide(r, m):
    """月 m に持つもの（m−1 月末までのデータだけ）→ (重み or None, 並べられた集合, N, k)"""
    sc = F.signal(r, m, FROZEN['J'], FROZEN.get('skip', 0))
    N = len(sc); k = k_of(N)
    w = F.weights(r, None, m, dict(FROZEN, k=k))
    return w, sorted(sc), N, k


def run_rule(r, lag=0, rhold=None, months=None, leak=0):
    """lag=1: 月 m に decide(r, m−1) を持つ。rhold: 持っている期間のリターン（既定は r）。leak: 検出力の検査用に未来へずらす"""
    rhold = rhold or r
    months = months or sorted(set().union(*[set(s) for s in r.values()]))
    ret, ew, tv, tv_ew, held, info = {}, {}, {}, {}, {}, {'missing_held': [], 'N_k': {}}
    wp = wpe = None
    for m in months:
        if m > LAST:
            break
        md = h.add_months(m, -lag + leak)
        w, univ, N, k = decide(r, md)
        if w is None:
            wp = wpe = None
            continue
        fill = {}
        for i in univ:
            if m in rhold.get(i, {}):
                fill[i] = rhold[i][m]
            else:
                fill[i] = 0.0
                if i in w:
                    info['missing_held'].append((m, i))
        rp = sum(wi * fill[i] for i, wi in w.items())
        we = {i: 1 / len(univ) for i in univ}
        re = sum(we[i] * fill[i] for i in univ)
        tv[m] = 1.0 if wp is None else 0.5 * sum(abs(w.get(i, 0) - wp.get(i, 0)) for i in set(w) | set(wp))
        tv_ew[m] = 1.0 if wpe is None else 0.5 * sum(abs(we.get(i, 0) - wpe.get(i, 0)) for i in set(we) | set(wpe))
        ret[m], ew[m], held[m] = rp, re, sorted(w)
        info['N_k'][m] = (N, k)
        wp = {i: wi * (1 + fill[i]) / (1 + rp) for i, wi in w.items()} if rp > -1 else None
        wpe = {i: wi * (1 + fill[i]) / (1 + re) for i, wi in we.items()} if re > -1 else None
    return {'ret': ret, 'ew': ew, 'tv': tv, 'tv_ew': tv_ew, 'held': held, 'info': info}


def st(ret, bench, a=None, b=None, tv=None, cost=COST):
    x = h.stats(ret, bench, None, a, b, turnover=tv, cost=cost if tv else 0.0)
    if x:
        x.pop('sharpe', None); x.pop('bench_sharpe', None)
    return x


def net(ret, tv, cost=COST):
    return {m: ret[m] - tv.get(m, 0.0) * cost for m in ret}


def cal_year_excess(rn, bench, ms):
    out = {}
    for y in sorted({m // 100 for m in ms}):
        mm = [m for m in ms if m // 100 == y]
        a = math.prod(1 + rn[m] for m in mm) - 1
        b = math.prod(1 + bench[m] for m in mm) - 1
        out[y] = round((a - b) * 100, 2)
    return out


def top4(rn, bench, ms):
    cy = cal_year_excess(rn, bench, ms)
    tops = sorted(cy, key=lambda y: -cy[y])[:4]
    rest = [m for m in ms if m // 100 not in tops]
    xr = {m: rn[m] for m in rest}; xb = {m: bench[m] for m in rest}
    s_rest = h.stats(xr, xb)
    # 対数の寄与の割合
    tot = sum(math.log(1 + rn[m]) - math.log(1 + bench[m]) for m in ms)
    part = sum(math.log(1 + rn[m]) - math.log(1 + bench[m]) for m in ms if m // 100 in tops)
    return {'calendar_year_excess_pct': cy, 'top4_years': {str(y): cy[y] for y in tops},
            'rest_excess_pct_yr': s_rest['excess'] if s_rest else None, 'rest_t': s_rest['t'] if s_rest else None,
            'rest_months': len(rest), 'share_of_log_excess_from_top4': round(part / tot, 2) if tot else None,
            'total_log_excess': round(tot, 3)}


def capm(y, x, ms):
    ys = [y[m] for m in ms]; xs = [x[m] for m in ms]
    mx, my = S.mean(xs), S.mean(ys)
    sxx = sum((a - mx) ** 2 for a in xs); sxy = sum((a - mx) * (b - my) for a, b in zip(xs, ys))
    beta = sxy / sxx
    res = [b - my - beta * (a - mx) for a, b in zip(xs, ys)]
    alpha = my - beta * mx
    se_a = math.sqrt(sum(e * e for e in res) / (len(ms) - 2) / len(ms))
    corr = sxy / math.sqrt(sxx * sum((b - my) ** 2 for b in ys))
    return {'beta': round(beta, 3), 'alpha_pct_yr': round(alpha * 1200, 2), 'alpha_t': round(alpha / se_a, 2), 'corr': round(corr, 3), 'months': len(ms)}


def ann_turnover(tv, ms):
    by = {}
    for m in ms[1:]:
        by.setdefault(m // 100, []).append(tv.get(m, 0.0))
    full = {y: sum(v) for y, v in by.items() if len(v) == 12}
    return round(S.mean(full.values()), 2) if full else None, {str(y): round(v, 2) for y, v in full.items()}

