import os, sys, json, math, statistics as S, datetime, random, pickle
SP = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, SP)
from run import *
P = pickle.load(open(os.path.join(SP, 'part1.pkl'), 'rb'))
R, L1, ser = P['R'], P['L1'], P['ser']
spy, acwi, qqq = ser['SPY'], ser['ACWI'], ser['QQQ']
rmain = {s: ser[s] for s in MAIN}
ms = sorted(R['ret'])
rn = net(R['ret'], R['tv'])
O = {}

# ── 紙の同じ月: French 49業種の凍結した規則（fam_indmom.run） ──
pr = F.run(FROZEN)
r49, _cap = F._load(49)
pms = [m for m in ms if m in pr['ret']]
print('paper months', pms[0], pms[-1], len(pms))
paper_vs_mkt = st(pr['ret'], pr['bench'], pms[0], pms[-1], pr['turnover'])
ew49 = {}
for m in pms:
    sc = F.signal(r49, m, FROZEN['J'], FROZEN.get('skip', 0))
    ew49[m] = S.mean(r49[i].get(m, 0.0) for i in sc)
paper_vs_ew49 = st(pr['ret'], ew49, pms[0], pms[-1], pr['turnover'])
pnet = net(pr['ret'], pr['turnover'])
arm_etf = {m: rn[m] - R['ew'][m] for m in pms}
arm_paper = {m: pnet[m] - ew49[m] for m in pms}
arm_paper_mkt = {m: pnet[m] - pr['bench'][m] for m in pms}
O['paper_same_months'] = {'rule_vs_US_market': paper_vs_mkt, 'rule_vs_EW49': paper_vs_ew49,
                          'etf_arm_on_paper_arm': capm(arm_etf, arm_paper, pms),
                          'etf_arm_on_paper_vs_mkt': capm(arm_etf, arm_paper_mkt, pms)}
print('paper vs mkt', paper_vs_mkt); print('paper vs ew49', paper_vs_ew49); print('regress', O['paper_same_months']['etf_arm_on_paper_arm'])
per = {'〜2007-12': (None, 200712), '2008-01〜2015-12': (200801, 201512), '2016-01〜2026-08': (201601, 202608)}
O['paper_sub'] = {nm: {'vs_mkt': st(pr['ret'], pr['bench'], a or pms[0], b, pr['turnover']), 'vs_EW49': st(pr['ret'], ew49, a or pms[0], b, pr['turnover'])} for nm, (a, b) in per.items()}
for nm, v in O['paper_sub'].items():
    print('paper', nm, v['vs_mkt']['excess'], v['vs_mkt']['t'], '| vs EW49', v['vs_EW49']['excess'], v['vs_EW49']['t'])

# ── Vanguard（事後・参考） ──
rv = {s: ser[s] for s in VANG}
V = run_rule(rv)
vms = sorted(V['ret'])
Nv = {m: V['info']['N_k'][m][0] for m in vms}
vms10 = [m for m in vms if Nv[m] == 10]
O['vanguard'] = {'window': [vms[0], vms[-1]], 'all10_from': vms10[0],
                 'vs_EW10': st(V['ret'], V['ew'], tv=V['tv']), 'vs_SPY': st(V['ret'], spy, tv=V['tv']),
                 'EW10_vs_SPY': st(V['ew'], spy), 'vs_QQQ': st(V['ret'], qqq, tv=V['tv']),
                 'sub': {nm: {'vs_EW10': st(V['ret'], V['ew'], a, b, V['tv']), 'vs_SPY': st(V['ret'], spy, a, b, V['tv'])} for nm, (a, b) in per.items()},
                 'annual_turnover': ann_turnover(V['tv'], vms)[0]}
VL1 = run_rule(rv, lag=1)
O['vanguard']['lag1_vs_EW10'] = st(VL1['ret'], VL1['ew'], tv=VL1['tv'])
vn = net(V['ret'], V['tv'])
O['vanguard']['top4_vs_EW10'] = {k: v for k, v in top4(vn, V['ew'], vms).items() if k != 'calendar_year_excess_pct'}
print('VANG', O['vanguard']['window'], 'vs EW', O['vanguard']['vs_EW10']); print('VANG vs SPY', O['vanguard']['vs_SPY']); print('VANG lag1', O['vanguard']['lag1_vs_EW10'])
for nm, v in O['vanguard']['sub'].items():
    if v['vs_EW10']: print('  V', nm, v['vs_EW10']['excess'], v['vs_EW10']['t'])
# 米国の業種（Vanguard）の選ぶ腕と、世界の業種ETFの選ぶ腕の重なり
PAIR = dict(zip(MAIN, ['VGT', 'VHT', 'VFH', 'VDE', 'VOX', 'VIS', 'VDC', 'VCR', 'VAW', 'VPU']))
common = [m for m in ms if m in V['ret'] and m in vms10 and m in R['info']['N_k'] and R['info']['N_k'][m][0] == 10]
same = sum(1 for m in common if {PAIR[x] for x in R['held'][m]} == set(V['held'][m]))
jac = S.mean(len({PAIR[x] for x in R['held'][m]} & set(V['held'][m])) / len({PAIR[x] for x in R['held'][m]} | set(V['held'][m])) for m in common)
arm_v = {m: vn[m] - V['ew'][m] for m in common}
O['overlap_with_us_sectors'] = {'months': len(common), 'same_3_sectors_share': round(same / len(common), 2), 'mean_jaccard': round(jac, 2),
                                'arm_corr_global_vs_us_vanguard': capm({m: arm_etf.get(m, rn[m] - R['ew'][m]) for m in common}, arm_v, common),
                                'arm_on_paper_US49': capm({m: rn[m] - R['ew'][m] for m in common if m in arm_paper}, arm_paper, [m for m in common if m in arm_paper])}
print('overlap', O['overlap_with_us_sectors'])

# ── 翌営業日に執行（事後・参考）: 信号は月末、持つのは翌月の最初の取引日の終値から次の月の最初の取引日の終値まで ──
def first_day_series(sym):
    rows, divs, spl = D.daily(sym)
    fd = {}
    for d, c, a in rows:
        m = d.year * 100 + d.month
        if m not in fd:
            fd[m] = a
    ks = sorted(fd)
    return {a: fd[b] / fd[a] - 1 for a, b in zip(ks, ks[1:]) if h.add_months(a, 1) == b and b <= 202609}
rhold = {s: first_day_series(s) for s in MAIN}
spy_h = first_day_series('SPY'); acwi_h = first_day_series('ACWI')
D1 = run_rule(rmain, rhold=rhold)
O['next_day_exec'] = {'vs_EW': st(D1['ret'], D1['ew'], tv=D1['tv']), 'vs_SPY_same_days': st(D1['ret'], spy_h, tv=D1['tv']),
                      'vs_ACWI_same_days': st(D1['ret'], acwi_h, 200804, tv=D1['tv'])}
print('next day exec', O['next_day_exec']['vs_EW'])

# ── 今の持ち物（2026-08 末までの信号で 2026-09 に持つもの） ──
w, univ, N, k = decide(rmain, 202609)
sc = F.signal(rmain, 202609, 12, 0)
O['current_picks_for_2026_09'] = {'hold': sorted(w), 'N': N, 'k': k, 'score_12m_pct': {i: round(v * 100, 1) for i, v in sorted(sc.items(), key=lambda kv: -kv[1])}}
print('current', O['current_picks_for_2026_09'])
freq = {}
for m in ms:
    for i in R['held'][m]:
        freq[i] = freq.get(i, 0) + 1
O['hold_frequency_months'] = dict(sorted(freq.items(), key=lambda kv: -kv[1]))
O['hold_frequency_share'] = {i: round(v / len(ms), 2) for i, v in O['hold_frequency_months'].items()}
print('freq', O['hold_frequency_share'])

# ── QQQ（この利用者の主力と同じ指数）との比較・参考 ──
O['vs_QQQ'] = st(R['ret'], qqq, tv=R['tv'])
print('vs QQQ', O['vs_QQQ'])

# ── 先読みの検査 ──
def trunc(r, M):
    return {s: {m: v for m, v in x.items() if m <= M} for s, x in r.items()}
cuts = [200512, 200809, 201203, 201606, 202003, 202312]
bad = 0; checked = 0
for M in cuts:
    T = run_rule(trunc(rmain, M))
    for m in T['ret']:
        checked += 1
        if abs(T['ret'][m] - R['ret'][m]) > 1e-12 or abs(T['tv'][m] - R['tv'][m]) > 1e-12 or T['held'][m] != R['held'][m]:   # 1e-12: set の並びで和の順が変わる丸め（1e-16）だけを許す
            bad += 1
# 持ち物の前置き検査: 月 M までで切ったデータで決めた「月 M+1 の持ち物」が全データのそれと一致するか（全ての月で）
pos_bad = pos_n = 0
leak_bad = 0
for M in [m for m in ms if m < 202608]:
    T = trunc(rmain, M)
    m1 = h.add_months(M, 1)
    wt = decide(T, m1)[0]; wf = decide(rmain, m1)[0]
    pos_n += 1
    pos_bad += (wt != wf)
    # 検出力: 窓を1か月未来へずらした版（月 M+1 に decide(M+2) を持つ＝M+1 月のリターンを覗く）
    lt = decide(T, h.add_months(M, 2))[0]; lf = decide(rmain, h.add_months(M, 2))[0]
    leak_bad += (lt != lf)
O['lookahead_test'] = {'truncate_cuts': cuts, 'months_compared_ret_tv_held': checked, 'mismatch': bad,
                       'positions_prefix_checked': pos_n, 'positions_mismatch': pos_bad,
                       'power_future_window_mismatch': f'{leak_bad}/{pos_n}',
                       'note': '比較は 1e-12 の許容（set の並びで和の順が変わる 1e-16 の丸めだけを許す）'}
print('lookahead', O['lookahead_test'])
json.dump(O, open(os.path.join(SP, 'part2.json'), 'w'), ensure_ascii=False, indent=1, default=str)
pickle.dump({'V': V, 'D1': D1, 'pr_ret': pr['ret'], 'pr_bench': pr['bench'], 'pr_tv': pr['turnover'], 'ew49': ew49}, open(os.path.join(SP, 'part2.pkl'), 'wb'))

