import os, sys, json, math, random, pickle, statistics as S
SP = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, SP)
from run import *
P = pickle.load(open(os.path.join(SP, 'part1.pkl'), 'rb'))
R, ser = P['R'], P['ser']
rmain = {s: ser[s] for s in MAIN}
spy, acwi = ser['SPY'], ser['ACWI']
ms = sorted(R['ret'])
O = {}
# 同じ土俵・同じ本数を毎月でたらめに選ぶ（費用も同じ）＝偶然の分布
univ = {m: sorted(F.signal(rmain, m, 12, 0)) for m in ms}
kk = {m: R['info']['N_k'][m][1] for m in ms}
rule_ex = st(R['ret'], R['ew'], tv=R['tv'])['excess']
rnd = []; rnd_g = []
random.seed(20260928)
for it in range(2000):
    ret, tv = {}, {}
    wp = None
    for m in ms:
        pick = random.sample(univ[m], kk[m])
        w = {i: 1 / len(pick) for i in pick}
        rp = sum(w[i] * rmain[i][m] for i in w)
        tv[m] = 1.0 if wp is None else 0.5 * sum(abs(w.get(i, 0) - wp.get(i, 0)) for i in set(w) | set(wp))
        ret[m] = rp
        wp = {i: wi * (1 + rmain[i][m]) / (1 + rp) for i, wi in w.items()}
    a = st(ret, R['ew'], tv=tv); g = st(ret, R['ew'])
    rnd.append(a['excess']); rnd_g.append(g['ex_arith'])
rnd.sort(); rnd_g.sort()
rule_g = st(R['ret'], R['ew'])['ex_arith']
O['random_picks_null'] = {'sims': 2000, 'rule_excess_vs_EW': rule_ex, 'random_median': round(S.median(rnd), 2),
