"""税の模擬（特定口座・源泉あり／NISA）。月末の終値（分割調整済み）と月ごとの分配（権利落ち日の月）で、銘柄ごとに総平均法の取得単価を持つ"""
import os, sys, json, math, pickle, statistics as S
SP = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, SP)
from run import *
P = pickle.load(open(os.path.join(SP, 'part1.pkl'), 'rb'))
R, ser = P['R'], P['ser']
rmain = {s: ser[s] for s in MAIN}

def px_div(sym):
    rows, divs, spl = D.daily(sym)
    close, dv = {}, {}
    for d, c, a in rows:
        m = d.year * 100 + d.month
        close[m] = c
    for d, amt in divs.items():
        m = d.year * 100 + d.month
        dv[m] = dv.get(m, 0.0) + amt
    return close, dv
PX = {s: px_div(s) for s in MAIN + ['SPY', 'ACWI']}

def simulate(targets, rate_gain, rate_div, carry=False, cost=0.001):
    ms = sorted(targets)
    units, avg = {}, {}
    cash = 1.0
    G = T = 0.0
    cf = []                     # [(年, 残り)]
    buys_by_year, val_by_year = {}, {}
    V = 1.0
    for idx, m in enumerate(ms):
        p0m = h.add_months(m, -1)
        P0 = {i: PX[i][0][p0m] for i in set(units) | set(targets[m])}
        Vpre = cash + sum(units.get(i, 0) * P0[i] for i in units)
        y = m // 100
        if idx > 0 and ms[idx - 1] // 100 != y:     # 年が替わった: 繰越の整理と年の締め
            G_prev = G
            if carry:
                if G_prev < 0:
                    cf.append([y - 1, -G_prev])
                cf = [c for c in cf if c[0] >= y - 3]
            G = T = 0.0
        w = targets[m]
        pay = 0.0
        for _ in range(6):
            Vt = Vpre - pay
            real = 0.0; sells = buys = 0.0
            for i in set(units) | set(w):
                cur = units.get(i, 0) * P0[i]
                d = w.get(i, 0) * Vt - cur
                if d < 0:
                    real += (-d / P0[i]) * (P0[i] - avg[i]); sells += -d
                else:
                    buys += d
            tc = cost * (buys + sells) / 2
            cfa = sum(c[1] for c in cf) if carry else 0.0
            req = rate_gain * max(0.0, G + real - cfa)
            newpay = (req - T) + tc
            if abs(newpay - pay) < 1e-12:
                break
            pay = newpay
        # 実行
        Vt = Vpre - pay
        for i in set(units) | set(w):
            cur = units.get(i, 0) * P0[i]
            d = w.get(i, 0) * Vt - cur
            if d < 0:
                u = -d / P0[i]
                G += u * (P0[i] - avg[i])
                units[i] -= u
                if units[i] < 1e-15:
                    units.pop(i); avg.pop(i)
            elif d > 0:
                u = d / P0[i]
                avg[i] = (units.get(i, 0) * avg.get(i, 0) + d) / (units.get(i, 0) + u)
                units[i] = units.get(i, 0) + u
        cfa = sum(c[1] for c in cf) if carry else 0.0
        req = rate_gain * max(0.0, G - cfa)
        T = req
        cash = 0.0
        buys_by_year[y] = buys_by_year.get(y, 0.0) + buys
        # 月 m の中: 分配（税引き後は現金・翌月の入れ替えで再投資）
        dcash = sum(units[i] * PX[i][1].get(m, 0.0) for i in units) * (1 - rate_div)
        cash += dcash
        V = cash + sum(units[i] * PX[i][0][m] for i in units)
        val_by_year.setdefault(y, []).append(V)
    # 最後に全部売る
    m = ms[-1]
    real = sum(units[i] * (PX[i][0][m] - avg[i]) for i in units)
    G += real
    if carry:
        # 同じ年の G に繰越を当てる
        cfa = sum(c[1] for c in cf)
    else:
        cfa = 0.0
    req = rate_gain * max(0.0, G - cfa)
    V_final = V - (req - T)
    yrs = len(ms) / 12
    turn = {y: buys_by_year[y] / S.mean(val_by_year[y]) for y in buys_by_year if len(val_by_year[y]) == 12}
    return {'from': ms[0], 'to': ms[-1], 'years': round(yrs, 1), 'final_multiple': round(V_final, 3), 'cagr_pct': round((V_final ** (1 / yrs) - 1) * 100, 2),
            'buys_per_year_over_avg_value': round(S.mean(list(turn.values())[1:]), 2) if len(turn) > 1 else None}

ms = sorted(R['ret'])
tg_rule = {m: {i: 1 / len(R['held'][m]) for i in R['held'][m]} for m in ms}
tg_ew = {}
for m in ms:
    sc = F.signal(rmain, m, 12, 0)
    tg_ew[m] = {i: 1 / len(sc) for i in sc}
tg_spy = {m: {'SPY': 1.0} for m in ms}
ms_a = [m for m in ms if m >= 200805]
tg_acwi = {m: {'ACWI': 1.0} for m in ms_a}
REG = {'課税なし（参考）': (0, 0, False), 'NISA成長投資枠（米国の源泉10%だけ）': (0, 0.10, False),
       '特定口座・繰越控除なし': (0.20315, 0.2828, False), '特定口座・確定申告で3年の繰越控除': (0.20315, 0.2828, True)}
O = {}
for nm, (rg, rd, cy) in REG.items():
    O[nm] = {'規則': simulate(tg_rule, rg, rd, cy), '等加重10本（毎月戻す）': simulate(tg_ew, rg, rd, cy), 'SPY買い持ち': simulate(tg_spy, rg, rd, cy)}
    tg_rule_a = {m: tg_rule[m] for m in ms_a}
    O[nm]['規則（ACWIの窓）'] = simulate(tg_rule_a, rg, rd, cy)
    O[nm]['ACWI買い持ち'] = simulate(tg_acwi, rg, rd, cy)
    for k in ('規則', '等加重10本（毎月戻す）', 'SPY買い持ち'):
        print(nm, k, O[nm][k])
    print(nm, 'ACWI win: rule', O[nm]['規則（ACWIの窓）']['cagr_pct'], 'ACWI', O[nm]['ACWI買い持ち']['cagr_pct'])
json.dump(O, open(os.path.join(SP, 'tax.json'), 'w'), ensure_ascii=False, indent=1)
